INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Счет Трейд Ресурс 12.10 КБТ в загрузку OData', 'Счёт ООО «ВГ-ТРЕЙД» (Weissgauff) № 1177 от 12.10.2026 по правилу «Создание файла для OData». Восемь колонок: Артикул (колонка «Код», текстом), Штрихкод (из счёта, текстом), Наименование (как в счёте), Количество, Цена с НДС (из счёта), Страна, Номер ГТД, Номер РНПТ. Страна, ГТД и РНПТ взяты из УПД № 261012002/2 от 12.10.2026; 18 позиций счёта, разбитые в УПД по разным декларациям, разделены так же: 151 строка счёта → 175 строк. ГТД в 91 строке, РНПТ в 69 (по признаку прослеживаемости в УПД), в 15 строках номера нет в самом УПД (белорусские плиты, духовые шкафы, холодильники), у 6 из них нет и страны. Итог: 212 шт, 2 570 524,80 руб. — сходится со счётом и УПД до копейки.', '/converted/schet-treid-resurs-12-10-kbt-v-zagruzku-odata.xlsx', 'Счет Трейд Ресурс 12.10 КБТ в загрузку OData.xlsx', 'converted/schet-treid-resurs-12-10-kbt-v-zagruzku-odata.xlsx', 16142);